  d < fm_b FAM - 1 -> r < 0 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB1LA_1LC1RC_0LA1RD_0RB0LC d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
