  | 1, (StD, S0) => [SWin 3;SCycL 3 0;SWin 3;SWinL 7;SCycR 5;SWinR 12]
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWinL 6]
  | _, _ => []
  end.

