  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LA1RB_1LA0RB_______
  | _, _ => iarm0_0_1RB1LC_0LA1RB_1LA0RB_______   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_0LA1RB_1LA0RB_______ : LRule :=
  mkLRule (mkC StB (mkS [S1;S0] [S1;S0] 1 0 []) S0 (mkS [] [] 0 0 []))
